#include <iostream>

// Example demonstrating inline function and potential optimizations
inline int add(int a, int b) {
    return a + b;  // Simple addition; compiler may inline this
}

int main() {
    const int iterations = 1000000;
    int sum = 0;
    for(int i = 0; i < iterations; ++i) {
        sum += add(1, 2);  // Invariant expression: 'add(1, 2)' may be inlined and hoisted
    }
    std::cout << "Sum: " << sum << std::endl;  // Output: Sum: 3000000
    return 0;
}
